import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"19、【臨】 兌下坤上","description":"周易尚氏學 - 19、【臨】 兌下坤上","frontmatter":{"title":"19、【臨】 兌下坤上","description":"周易尚氏學 - 19、【臨】 兌下坤上"},"headers":[],"relativePath":"classics/shangshi/024.md","filePath":"classics/shangshi/024.md"}'),s={name:"classics/shangshi/024.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_19、【臨】-兌下坤上" tabindex="-1">19、【臨】 兌下坤上 <a class="header-anchor" href="#_19、【臨】-兌下坤上" aria-label="Permalink to “19、【臨】 兌下坤上”">​</a></h1><p>釋詁。臨視也。毀梁哀七年。有臨天下之言焉。注。臨撫有之也。卦以震君臨四陰。正撫有也。故曰臨。臨闢醜。陽息卦。故曰元亨。左傳雲。不行之謂臨。行而不已。則至八月而兇矣。故又曰利貞。言利於貞定也。月卦始子復。至未遁正八月。故鄭陸虞皆以八月為遁。而虞氏以殺君父說兇義則非。殺君父皆否遁所同有。胡獨八月兇乎。按易林恆之臨雲。神之在醜。破逆為咎。不利西南。商人休止。臨闢醜。震為神。故曰神之在醜。乃行至未而破醜。故曰破逆為咎。又按漢書翼奉傳。平昌侯三來見臣。皆以正日加邪時。孟康曰。謂乙丑之日。醜為正。日加未而來。未破醜。故曰邪時。陸績易傳至於八月兇注曰。建醜至未也。八遁亦以未破醜說兇義。徒以弒君父為說。何以辭於其它消卦乎。幾易言八月七日。皆言爻數。後儒往往以殷正周正為說。皆夢吃語也。</p><p>彖曰。臨。剛來浸而長。說而順。剛中而應。大亨以正。天之道也。至於八月有兇。消不久也。</p><p>通消卦。故曰不久。</p><p>象曰。澤上有地。臨。君子以教思無窮。容保民無疆。</p><p>震兌皆為言。故曰教思無窮。坤為民。震為仁。故曰容保民。坤廣大。故曰無疆。</p><p>初九。鹹臨。貞吉。</p><p>鹹感也。初二爻皆有應。故皆曰鹹臨。貞卜問也。</p><h3 id="象曰。鹹臨貞吉。志行正也。" tabindex="-1">象曰。鹹臨貞吉。志行正也。 <a class="header-anchor" href="#象曰。鹹臨貞吉。志行正也。" aria-label="Permalink to “象曰。鹹臨貞吉。志行正也。”">​</a></h3><p>坤為志。應在坤。皆當位。故曰志行正。</p><p>九二。成臨。吉。無不利。</p><p>承遇陰則通。故曰無不利。</p><h3 id="象曰。鹹臨吉無不利。未順命也。" tabindex="-1">象曰。鹹臨吉無不利。未順命也。 <a class="header-anchor" href="#象曰。鹹臨吉無不利。未順命也。" aria-label="Permalink to “象曰。鹹臨吉無不利。未順命也。”">​</a></h3><p>二必升五。得尚於中行。而卦以不利為義。故曰未順命。</p><p>六三。甘臨。無攸利。既憂之。無咎。</p><p>說文。甘美也。三獨近二。陰順陽。言甘於順二也。然不當位。無應。故無所利。坤為憂。知無所利而優之。故無咎也。</p><h3 id="象曰。甘臨。位不當也。既憂之。咎不長也。" tabindex="-1">象曰。甘臨。位不當也。既憂之。咎不長也。 <a class="header-anchor" href="#象曰。甘臨。位不當也。既憂之。咎不長也。" aria-label="Permalink to “象曰。甘臨。位不當也。既憂之。咎不長也。”">​</a></h3><p>不長謂不久。</p><p>六四。至臨。無咎。</p><p>虞翻曰。至下也。謂下應初。當位有實。故無咎。</p><h3 id="象曰。至臨無咎。" tabindex="-1">象曰。至臨無咎。 <a class="header-anchor" href="#象曰。至臨無咎。" aria-label="Permalink to “象曰。至臨無咎。”">​</a></h3><p>位當也。</p><p>六五。知臨。大君之宜。吉。</p><p>知音智。言宜知幾也。震為大君。象失傳。詳焦氏易詁九二震主交。應在五。二五相上下。皆當位。故曰大君之宜。言二宜升五也。</p><h3 id="象曰。大君之宜。行中之謂也。" tabindex="-1">象曰。大君之宜。行中之謂也。 <a class="header-anchor" href="#象曰。大君之宜。行中之謂也。" aria-label="Permalink to “象曰。大君之宜。行中之謂也。”">​</a></h3><p>二五皆中位。故曰行中。知臨者。言宜知幾。與二相上下也。</p><p>上六。敦臨。吉。無咎。</p><p>陽息即至三。上稍止即有應。故曰敦臨。敦與屯與頓皆通。有止意待意。義詳復卦。言稍待即有應。故曰志在內。內謂三也。故復五六亦曰敦復。言五少遲。陽即息至二。有應。與此同也。舊解訓敦為厚。非。</p><h3 id="象曰。敦臨之吉。" tabindex="-1">象曰。敦臨之吉。 <a class="header-anchor" href="#象曰。敦臨之吉。" aria-label="Permalink to “象曰。敦臨之吉。”">​</a></h3><p>志在內也言頓止之故。因陽息即至三。有應也。易之道貴將來。將來有應。故吉。不然內無應。何吉之有。凡雲志在內。志在外者。皆謂應爻。九家謂志在二升五。清儒皆宗之。由誤解敦字故也。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
